import 'dart:convert';
import 'dart:io';

// Run from the repository root. Both runtimes embed exactly the same sources.
void main(List<String> args) {
  final sources = {
    'JOB_SCRIPT': 'scripts/remote/job.sh',
    'MANAGER_SCRIPT': 'scripts/remote/manage.py',
    'INSTALL_TEMPLATE': 'scripts/remote/install.sh.template',
    'STATUS_SCRIPT': 'scripts/remote/status.sh',
    'INSPECTOR_SCRIPT': 'scripts/remote/inspect.py',
  };
  final ts = StringBuffer('// Generated by tool/generate.dart. Do not edit.\n');
  final dart = StringBuffer(
    "// Generated by tool/generate.dart. Do not edit.\nimport 'dart:convert';\n\n",
  );
  for (final entry in sources.entries) {
    final source = File(entry.value).readAsStringSync();
    ts.writeln('export const ${entry.key} = ${jsonEncode(source)};');
    final name = entry.key
        .toLowerCase()
        .split('_')
        .indexed
        .map(
          (e) =>
              e.$1 == 0 ? e.$2 : '${e.$2[0].toUpperCase()}${e.$2.substring(1)}',
        )
        .join();
    dart.writeln(
      "final $name = utf8.decode(base64Decode('${base64Encode(utf8.encode(source))}'));\n",
    );
  }
  final ranges = File('contracts/network-ranges.json').readAsStringSync();
  dart.writeln(
    "final networkRanges = (jsonDecode(utf8.decode(base64Decode('${base64Encode(utf8.encode(ranges))}'))) as Map<String, dynamic>).map((key, value) => MapEntry(key, (value as List).cast<String>()));",
  );
  final files = {
    'src/server/remote.generated.ts': ts.toString(),
    'packages/five_a_core/lib/src/remote_generated.dart': dart.toString(),
  };
  for (final entry in files.entries) {
    final file = File(entry.key);
    if (args.contains('--check')) {
      if (!file.existsSync() || file.readAsStringSync() != entry.value) {
        stderr.writeln(
          '${entry.key} is stale. Run fvm dart run tool/generate.dart.',
        );
        exitCode = 1;
      }
    } else {
      file.parent.createSync(recursive: true);
      file.writeAsStringSync(entry.value);
    }
  }
}
